package tv.clearstream;

import android.app.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.Handler;
import android.text.*;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import java.util.*;
import tv.clearstream.core.ChannelNames;
import tv.clearstream.core.SourceManagement;

/** Bounded TV views; atomic delete and persistent undo live in SourceStore. */
final class SourceManager implements AutoCloseable {
 interface Actions {
  void importSources();void refreshSubscriptions();void inspect(List<Channel> targets);void openChannel(Channel channel);
  boolean checking();boolean busy();boolean active();void cancelChecks();void libraryChanged();
 }
 private interface Work {String run()throws Exception;}
 private interface Choice {void choose(int index);}
 private static final int CARD=0xff1b222b,BLUE=0xff4c9aff,MUTED=0xffa9b7c7,PAGE_SIZE=20;
 private static final String[] STATES={"全部状态","确定失效","待复检","未检测","连接/解析记录","收藏源"},PROTOCOLS={"全部协议","IPv6","IPv4","域名/双栈"};
 private final Activity activity;private final ClearApp app;private final Handler main;private final Actions actions;
 private LinearLayout parent,rows,selectionBar;private EditText search;private TextView counts,pageLabel;
 private TextView add,subscribe,probe,select,groupButton,stateButton,protocolButton,clean,clear,undo,allButton,regroup,remove,previous,next,resetSearch;
 private List<Channel> all=new ArrayList<>(),shown=new ArrayList<>();private final Set<Long> selected=new HashSet<>();private final Map<Long,String> selectedUrls=new HashMap<>();
 private String query="",group="全部分组",lastTag="";private int state,protocol,page;private boolean selection,mutation,queryCenterDown,closed;
 private final Runnable searchLater=()->{page=0;refresh();};
 SourceManager(Activity activity,ClearApp app,Handler main,Actions actions){this.activity=activity;this.app=app;this.main=main;this.actions=actions;}
 void render(LinearLayout destination){
  String restoreTag=lastTag;parent=destination;LinearLayout tools=row();add=button("＋ 导入源","source-import",actions::importSources);subscribe=button("刷新订阅","source-subscriptions",actions::refreshSubscriptions);
  probe=button("检测当前列表","source-probe",()->{if(actions.checking())actions.cancelChecks();else if(!blocked())actions.inspect(selection?selectedRows():new ArrayList<>(shown));});
  select=button("批量选择","source-select",()->{selection=!selection;if(!selection){selected.clear();selectedUrls.clear();}refresh();if(selection&&allButton.isEnabled())allButton.requestFocus();});for(TextView b:new TextView[]{add,subscribe,probe,select})addButton(tools,b);parent.addView(tools);
  LinearLayout find=row();search=new EditText(activity);search.setId(View.generateViewId());search.setSingleLine(true);search.setHint("搜名称、分组或地址");search.setHintTextColor(MUTED);search.setTextColor(Color.WHITE);font(search,18);search.setPadding(dp(10),0,dp(10),0);search.setShowSoftInputOnFocus(false);search.setImeOptions(EditorInfo.IME_ACTION_SEARCH);search.setContentDescription("搜索直播源");search.setTag("source-search");search.setText(query);search.setOnFocusChangeListener((v,f)->{if(f)lastTag="source-search";});
  search.setOnClickListener(v->keyboard(search));search.setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_DPAD_CENTER){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0)queryCenterDown=true;if(event.getAction()==KeyEvent.ACTION_UP){boolean open=queryCenterDown&&!event.isCanceled();queryCenterDown=false;if(open)keyboard(search);}return true;}if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_DOWN){hideKeyboard();if(rows!=null&&rows.getChildCount()>0&&rows.getChildAt(0).isFocusable())focusFirst();else groupButton.requestFocus();return true;}if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_UP){add.requestFocus();return true;}if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_RIGHT&&search.getSelectionStart()==search.getSelectionEnd()&&search.getSelectionEnd()==search.length()&&resetSearch!=null){resetSearch.requestFocus();return true;}return false;});
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();main.removeCallbacks(searchLater);main.postDelayed(searchLater,180);}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH){hideKeyboard();page=0;refresh();focusFirst();return true;}return false;});
  find.addView(search,new LinearLayout.LayoutParams(0,dp(42),1));resetSearch=button("重置筛选","source-reset",()->{group="全部分组";state=protocol=page=0;query="";search.setText("");refresh();});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(dp(130),dp(42));rp.leftMargin=dp(8);find.addView(resetSearch,rp);parent.addView(find);
  LinearLayout filters=row();groupButton=button("分组","source-group",this::chooseGroup);groupButton.setContentDescription("筛选分组");stateButton=button("状态","source-state",()->choose(STATES,state,i->{state=i;page=0;refresh();}));stateButton.setContentDescription("筛选检测状态");protocolButton=button("协议","source-protocol",()->choose(PROTOCOLS,protocol,i->{protocol=i;page=0;refresh();}));protocolButton.setContentDescription("筛选网络协议");for(TextView b:new TextView[]{groupButton,stateButton,protocolButton})addButton(filters,b);parent.addView(filters);
  LinearLayout destructive=row();clean=button("清理失效源","source-clean",this::confirmInvalid);clear=button("清空所有 IPTV 源","source-clear-all",this::confirmAll);clear.setTextColor(0xffffb1a8);undo=button("撤销删除","source-undo",this::restore);undo.setContentDescription("撤销上次删除");for(TextView b:new TextView[]{clean,clear,undo})addButton(destructive,b);parent.addView(destructive);
  selectionBar=row();allButton=button("全选当前结果","source-select-all",()->{boolean full=!shown.isEmpty()&&selected.containsAll(ids(shown));for(Channel c:shown)if(full){selected.remove(c.id);selectedUrls.remove(c.id);}else{selected.add(c.id);selectedUrls.put(c.id,c.url);}refresh();});regroup=button("批量改组","source-regroup",this::changeGroup);regroup.setContentDescription("批量改组");remove=button("删除选中","source-remove-selected",()->confirmSelected(selectedRows()));TextView unselect=button("清除选择","source-unselect",()->{selected.clear();selectedUrls.clear();refresh();});for(TextView b:new TextView[]{allButton,regroup,remove,unselect})addButton(selectionBar,b);parent.addView(selectionBar);
  counts=text("",14,MUTED);counts.setSingleLine(true);counts.setEllipsize(TextUtils.TruncateAt.END);counts.setPadding(dp(4),dp(4),dp(4),dp(5));parent.addView(counts,new LinearLayout.LayoutParams(-1,dp(28)));
  ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(false);scroll.setFocusable(false);rows=column();scroll.addView(rows);parent.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout pages=row();previous=button("上一页","source-previous",()->{page--;lastTag="";refresh();focusFirst();});next=button("下一页","source-next",()->{page++;lastTag="";refresh();focusFirst();});pageLabel=text("",14,MUTED);pageLabel.setGravity(Gravity.CENTER);pages.addView(previous,new LinearLayout.LayoutParams(0,dp(38),1));pages.addView(pageLabel,new LinearLayout.LayoutParams(dp(130),dp(38)));pages.addView(next,new LinearLayout.LayoutParams(0,dp(38),1));parent.addView(pages);refresh();View initial=parent.findViewWithTag(restoreTag);if(initial!=null&&initial.isEnabled())initial.requestFocus();else focusFirst();
 }
 void refresh(){
  if(parent==null||closed||activity.isDestroyed()||!actions.active())return;View before=activity.getCurrentFocus();String tag=before!=null&&before.getTag() instanceof String?(String)before.getTag():lastTag;
  all=app.store.all();Map<Long,String> current=new HashMap<>();for(Channel c:all)current.put(c.id,c.url);for(Iterator<Long> ids=selected.iterator();ids.hasNext();){Long id=ids.next();if(!Objects.equals(selectedUrls.get(id),current.get(id)))ids.remove();}selectedUrls.keySet().retainAll(selected);Set<String> groups=new LinkedHashSet<>();for(Channel c:all)groups.add(c.group);if(!group.equals("全部分组")&&!groups.contains(group))group="全部分组";
  shown=new ArrayList<>();for(Channel c:all)if(matches(c))shown.add(c);int pages=Math.max(1,(shown.size()+PAGE_SIZE-1)/PAGE_SIZE);page=Math.max(0,Math.min(page,pages-1));rows.removeAllViews();int firstRowId=View.NO_ID;
  for(int i=page*PAGE_SIZE;i<Math.min(shown.size(),(page+1)*PAGE_SIZE);i++){
   Channel c=shown.get(i);LinearLayout item=column();item.setId(View.generateViewId());if(i==page*PAGE_SIZE){firstRowId=item.getId();item.setNextFocusUpId((selection?allButton:stateButton).getId());}item.setPadding(dp(14),dp(6),dp(14),dp(6));item.setFocusable(true);item.setFocusableInTouchMode(true);item.setTag("source-row:"+c.id);item.setContentDescription("管理直播源："+c.name);styleFocus(item);
   TextView title=text((selection?(selected.contains(c.id)?"☑  ":"□  "):c.favorite?"★  ":"")+c.name+" · "+c.group,18,Color.WHITE);title.setSingleLine(true);title.setEllipsize(TextUtils.TruncateAt.END);item.addView(title);TextView detail=text(c.hint()+" · "+c.status,12,SourceManagement.clearable(c.status)?0xffffbd8f:MUTED);detail.setSingleLine(true);detail.setEllipsize(TextUtils.TruncateAt.END);item.addView(detail);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(62));p.setMargins(0,dp(3),0,dp(3));rows.addView(item,p);
   item.setOnClickListener(v->{if(mutation)return;lastTag="source-row:"+c.id;if(selection){if(!selected.add(c.id)){selected.remove(c.id);selectedUrls.remove(c.id);}else selectedUrls.put(c.id,c.url);refresh();}else actions.openChannel(c);});
  }
  if(shown.isEmpty()){TextView empty=text(all.isEmpty()?"暂无 IPTV 源，可导入或撤销上次删除":"没有匹配的源，可重置筛选",18,MUTED);empty.setGravity(Gravity.CENTER);rows.addView(empty,new LinearLayout.LayoutParams(-1,dp(64)));}
  counts.setText(mutation?"正在处理源库，请稍候…":"总计 "+all.size()+" 条 · 结果 "+shown.size()+" 条 · 已选 "+selected.size()+" 条");groupButton.setText("分组："+group);stateButton.setText("状态："+STATES[state]);protocolButton.setText("协议："+PROTOCOLS[protocol]);selectionBar.setVisibility(selection?View.VISIBLE:View.GONE);select.setText(selection?"完成选择":"批量选择");
  int undoCount=app.store.removalUndo().size();undo.setText("撤销删除"+(undoCount>0?" · "+undoCount:""));boolean busy=mutation||actions.busy();add.setEnabled(!busy);subscribe.setEnabled(!busy);clean.setEnabled(!busy);clear.setEnabled(!busy&&!all.isEmpty());undo.setEnabled(!busy&&undoCount>0);probe.setText(actions.checking()?"取消检测":selection?"检测选中":"检测当前列表");probe.setEnabled(!mutation&&(!actions.busy()||actions.checking()));select.setEnabled(!mutation);regroup.setEnabled(!busy&&!selected.isEmpty());remove.setEnabled(!busy&&!selected.isEmpty());allButton.setEnabled(!mutation&&!shown.isEmpty());allButton.setText(!shown.isEmpty()&&selected.containsAll(ids(shown))?"取消选择当前结果":"全选当前结果");previous.setEnabled(!mutation&&page>0);next.setEnabled(!mutation&&page+1<pages);pageLabel.setText((page+1)+" / "+pages);
  for(TextView b:new TextView[]{add,subscribe,probe,select})b.setNextFocusDownId(search.getId());search.setNextFocusUpId(add.getId());for(TextView b:new TextView[]{groupButton,stateButton,protocolButton})b.setNextFocusUpId(search.getId());groupButton.setNextFocusDownId(clean.getId());stateButton.setNextFocusDownId((clear.isEnabled()?clear:undo.isEnabled()?undo:clean).getId());protocolButton.setNextFocusDownId((undo.isEnabled()?undo:clear.isEnabled()?clear:clean).getId());clean.setNextFocusUpId(groupButton.getId());clear.setNextFocusUpId(stateButton.getId());undo.setNextFocusUpId(protocolButton.getId());
  clean.setNextFocusDownId(selection?allButton.getId():firstRowId);clear.setNextFocusDownId(selection?(regroup.isEnabled()?regroup:allButton).getId():firstRowId);undo.setNextFocusDownId(selection?selectionBar.getChildAt(3).getId():firstRowId);allButton.setNextFocusUpId(clean.getId());regroup.setNextFocusUpId(clear.getId());remove.setNextFocusUpId(undo.getId());selectionBar.getChildAt(3).setNextFocusUpId(undo.getId());for(int i=0;i<selectionBar.getChildCount();i++)selectionBar.getChildAt(i).setNextFocusDownId(firstRowId);
  if(before!=null&&before.isAttachedToWindow()&&before!=activity.getWindow().getDecorView())return;View restore=tag==null?null:parent.findViewWithTag(tag);if(restore!=null&&restore.isEnabled())restore.requestFocus();else focusFirst();
 }
 private boolean matches(Channel c){
  if(!group.equals("全部分组")&&!group.equals(c.group))return false;SourceManagement.State s=SourceManagement.classify(c.status);if(state==1&&s!=SourceManagement.State.INVALID||state==2&&s!=SourceManagement.State.RECHECK||state==3&&s!=SourceManagement.State.UNTESTED||state==4&&s!=SourceManagement.State.AVAILABLE||state==5&&!c.favorite)return false;
  boolean v6=c.isV6(),v4=!v6&&c.hint().startsWith("IPv4");if(protocol==1&&!v6||protocol==2&&!v4||protocol==3&&(v6||v4))return false;String q=query.trim();return q.isEmpty()||ChannelNames.matches(c.name,c.group,q)||c.url.toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT));
 }
 private void choose(String[] labels,int selected,Choice chosen){AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("筛选直播源").setSingleChoiceItems(labels,selected,(d,i)->{d.dismiss();chosen.choose(i);}).setNegativeButton("取消",null).create();dialog.show();}
 private void chooseGroup(){LinkedHashSet<String> values=new LinkedHashSet<>();values.add("全部分组");for(Channel c:all)values.add(c.group);String[] labels=values.toArray(new String[0]);choose(labels,Arrays.asList(labels).indexOf(group),i->{group=labels[i];page=0;refresh();});}
 private boolean blocked(){if(mutation||actions.busy()){toast(actions.checking()?"请先取消或等待检测结束":"源库正在更新，请稍候再操作");return true;}return false;}
 private void confirmAll(){if(blocked())return;List<Channel> snapshot=app.store.all();if(snapshot.isEmpty()){toast("已经没有 IPTV 源");return;}warning("清空所有 IPTV 源？","将清空全部 "+snapshot.size()+" 条 IPTV 直播源，包含收藏 "+favorites(snapshot)+" 条。\n影视网站和影片收藏保留。可撤销最近一次删除，新的删除会替换旧撤销记录。","确认清空",()->erase(snapshot,false,false));}
 private void confirmInvalid(){
  if(blocked())return;List<Channel> snapshot=new ArrayList<>();for(Channel c:app.store.all())if(SourceManagement.clearable(c.status))snapshot.add(c);if(snapshot.isEmpty()){new AlertDialog.Builder(activity).setTitle("没有已确认失效的源").setMessage("先用“检测当前列表”检测源。超时、缺少IPv6通道、需认证等放在“待复检”，可筛选后手动批量删除。").setPositiveButton("知道了",null).show();return;}
  LinearLayout info=column();info.setPadding(dp(24),dp(10),dp(24),dp(10));info.addView(text("确定失效 "+snapshot.size()+" 条，其中收藏 "+favorites(snapshot)+" 条。\n只清理404/410或返回非媒体网页的源；删除后可撤销。",17,Color.WHITE));CheckBox protect=new CheckBox(activity);protect.setText("保留收藏源");protect.setTextColor(Color.WHITE);protect.setChecked(true);info.addView(protect);AlertDialog d=new AlertDialog.Builder(activity).setTitle("清理失效源？").setView(info).setPositiveButton("确认清理",(x,w)->erase(snapshot,true,protect.isChecked())).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus());d.show();
 }
 void removeOne(Channel c){confirmSelected(Collections.singletonList(c));}
 private void confirmSelected(List<Channel> snapshot){if(blocked())return;if(snapshot.isEmpty()){toast("先选择要删除的源");return;}warning("删除所选 IPTV 源？","将删除选中的 "+snapshot.size()+" 条，包含收藏 "+favorites(snapshot)+" 条。\n影视网站保留，可撤销最近一次删除。","确认删除",()->erase(snapshot,false,false));}
 private void warning(String title,String message,String yes,Runnable confirmed){AlertDialog d=new AlertDialog.Builder(activity).setTitle(title).setMessage(message).setPositiveButton(yes,(x,w)->confirmed.run()).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_NEGATIVE).requestFocus());d.show();}
 private void erase(List<Channel> snapshot,boolean invalid,boolean keepFavorites){mutate(()->{int n=app.store.removeSources(snapshot,invalid,keepFavorites);return n>0?"已移除 "+n+" 条 IPTV 源，可撤销":"没有删除，源状态可能已变化或收藏被保留";});}
 private void restore(){mutate(()->{int n=app.store.undoRemoval(),left=app.store.removalUndo().size();return left>0?"已恢复 "+n+" 条，仍有 "+left+" 条待恢复；源库最多一万条":"撤销完成，恢复 "+n+" 条；已存在的源保留当前数据";});}
 private void changeGroup(){
  if(blocked())return;List<Channel> snapshot=selectedRows();if(snapshot.isEmpty()){toast("先选择要改组的源");return;}
  EditText input=new EditText(activity);input.setSingleLine(true);input.setTextColor(Color.WHITE);font(input,18);input.setHint("填写分组名称");input.setContentDescription("目标分组");input.setShowSoftInputOnFocus(false);input.setOnClickListener(v->keyboard(input));AlertDialog d=new AlertDialog.Builder(activity).setTitle("修改 "+snapshot.size()+" 条源的分组").setView(input).setPositiveButton("保存分组",null).setNegativeButton("取消",null).create();
  d.setOnShowListener(v->{d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{String name=input.getText().toString().trim();if(name.isEmpty()||name.codePointCount(0,name.length())>80){input.setError("分组名称为1至80个字");return;}d.dismiss();mutate(()->"已改组 "+app.store.regroupSources(snapshot,name)+" 条");});input.setOnKeyListener((field,key,event)->{if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_DOWN){d.getButton(AlertDialog.BUTTON_POSITIVE).requestFocus();return true;}return false;});input.requestFocus();});d.show();
 }
 private void mutate(Work work){if(blocked())return;mutation=true;if(actions.active())refresh();app.network.io.execute(()->{String message;try{message=work.run();}catch(Exception error){message="源库操作未完成，请稍后重试";}String result=message;main.post(()->{mutation=false;if(closed||activity.isDestroyed())return;actions.libraryChanged();if(actions.active())refresh();toast(result);});});}
 private List<Channel> selectedRows(){List<Channel> result=new ArrayList<>();for(Channel c:app.store.all())if(selected.contains(c.id)&&Objects.equals(selectedUrls.get(c.id),c.url))result.add(c);return result;}
 private static Set<Long> ids(List<Channel> list){Set<Long> ids=new HashSet<>();for(Channel c:list)ids.add(c.id);return ids;}
 private static int favorites(List<Channel> list){int count=0;for(Channel c:list)if(c.favorite)count++;return count;}
 private void focusFirst(){if(rows!=null&&rows.getChildCount()>0&&rows.getChildAt(0).isFocusable())rows.getChildAt(0).requestFocus();else if(undo!=null&&undo.isEnabled())undo.requestFocus();else if(add!=null)add.requestFocus();}
 private void keyboard(EditText input){input.setShowSoftInputOnFocus(true);input.requestFocus();((InputMethodManager)activity.getSystemService(Activity.INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);}
 private void hideKeyboard(){if(search!=null){((InputMethodManager)activity.getSystemService(Activity.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);search.setShowSoftInputOnFocus(false);}}
 void suspend(){queryCenterDown=false;main.removeCallbacks(searchLater);if(search!=null)search.setShowSoftInputOnFocus(false);}
 @Override public void close(){closed=true;main.removeCallbacks(searchLater);}
 private void toast(String message){Toast.makeText(activity,message,Toast.LENGTH_LONG).show();}
 private int dp(int value){android.util.DisplayMetrics m=activity.getResources().getDisplayMetrics();return Math.round(value*m.density*Math.min(1f,Math.min(m.widthPixels/m.density/960f,m.heightPixels/m.density/540f)));}
 private void font(TextView view,int size){view.setTextSize(android.util.TypedValue.COMPLEX_UNIT_PX,dp(size)*Math.min(1.15f,activity.getResources().getConfiguration().fontScale));}
 private TextView text(String label,int size,int color){TextView view=new TextView(activity);view.setText(label);view.setTextColor(color);font(view,size);return view;}
 private TextView button(String label,String tag,Runnable action){TextView b=text(label,16,Color.WHITE);b.setId(View.generateViewId());b.setTag(tag);b.setGravity(Gravity.CENTER);b.setPadding(dp(10),dp(7),dp(10),dp(7));b.setSingleLine(true);b.setEllipsize(TextUtils.TruncateAt.END);b.setFocusable(true);b.setFocusableInTouchMode(true);styleFocus(b);b.setOnClickListener(v->action.run());return b;}
 private void styleFocus(View view){view.setBackground(surface(false));view.setOnFocusChangeListener((v,f)->{v.setBackground(surface(f));if(f&&v.getTag() instanceof String)lastTag=(String)v.getTag();});}
 private GradientDrawable surface(boolean focused){GradientDrawable d=new GradientDrawable();d.setColor(focused?0xff30465e:CARD);d.setCornerRadius(dp(9));if(focused)d.setStroke(Math.max(1,dp(2)),BLUE);return d;}
 private LinearLayout row(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.HORIZONTAL);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.VERTICAL);return v;}
 private void addButton(LinearLayout row,View button){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(42),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(button,p);}
}
